-- PHASE 3: INSERT verbatim Status/Remarks
INSERT INTO public.case_status_updates (case_id, sort_order, body)
SELECT c.id, v.sort_order, v.body
FROM public.cases c
CROSS JOIN (VALUES
  (1, 'JANUARY 2023 – JUNE 2023: Attended the hearing on February 2, 2023.'),
  (2, 'Attended the hearing on March 16, 2023.'),
  (3, 'Received Constancia dated April 28, 2023 on June 7, 2023 resetting the Pre-Trial Conference on June 16, 2023 at 8:30 A.M.'),
  (4, 'Upon communication of the OIC Clerk of Court, Pre-Trial Conference on June 16, 2023 was cancelled and reset to July 20, 2023 at 8:30 AM.'),
  (5, 'JULY 2023 – DECEMBER 2023: Attended the hearing on July 20, 2023.'),
  (6, 'On August 8, 2023, the OSG received an Order dated July 20, 2023, resetting the hearing to September 14, 2023 at 8:30 in the morning.'),
  (7, 'Attended the hearing on September 14, 2023.'),
  (8, 'Under the Order dated September 14, 2023, the court noted the attendance of both counsels; defendant was not present and was indisposed. Plaintiff''s counsel manifested that she would talk with the defendant''s daughter regarding possible settlement.'),
  (9, 'Pre-Trial was set to November 15, 2023.'),
  (10, 'Attended the pre-trial on November 15, 2023.'),
  (11, 'For the presentation of Ms. Lydia Turingan, plaintiff''s first witness, on December 4, 2023.'),
  (12, 'JANUARY 2024 – AUGUST 2024: Presented witnesses Lydia B. Turingan and Nancy C. Guimmayen on December 4, 2023 and January 23, 2024, respectively.'),
  (13, 'Filed on January 29, 2024 a Motion for Marking and Formal Offer of Evidence dated January 26, 2024.'),
  (14, 'Received an Order dated February 14, 2024, which granted the marking of the Judicial Affidavits of the witnesses and admitted plaintiff''s exhibits.'),
  (15, 'Received an Order dated February 27, 2024 resetting the presentation of defendant''s evidence on April 11, 2024 as previously scheduled due to the Conference in PhilJA Training Center, Tagaytay City to be attended by the Judge.'),
  (16, 'Presentation of evidence on April 11, 2024 was waived by the defendant.'),
  (17, 'Under Order dated May 16, 2024, the presentation of defendant''s evidence was reset to June 11, 2024 in view of the absence of plaintiff''s counsel.'),
  (18, 'Filed a Manifestation and Motion clarifying that the absence of plaintiff''s counsel was due to information relayed by DOST-RO2 staff from defendant''s counsel that she would seek cancellation of the hearing due to the absence of Judicial Affidavit of a witness.'),
  (19, 'Under Order dated June 3, 2024, the Court ordered defendant''s counsel to furnish plaintiff''s counsel a copy of the Judicial Affidavit of her witness at least three days prior to the next hearing.'),
  (20, 'The June 11, 2024 hearing was cancelled by the Court.'),
  (21, 'Received from DOST-RO2 a copy of defendant''s JA. On July 11, 2024, an email request was sent to Engr. Magora in order for the OSG to prepare for the conduct of cross-examination of Florendo Usigan.'),
  (22, 'Attended meeting via Google Meet on July 29, 2024 in preparation of the cross-examination of Usigan.'),
  (23, 'Attended the hearing on July 30, 2024, which was reset to September 16, 2024 due to the unavailability of Usigan.'),
  (24, 'SEPTEMBER 2024 – OCTOBER 2024: Attended the September 16, 2024 Hearing.'),
  (25, 'Attended the October 17, 2024 Hearing.'),
  (26, 'Next scheduled hearing for the presentation of defendant''s last witness is set on December 12, 2024 at 8:30 A.M.'),
  (27, 'NOVEMBER 2024 – DECEMBER 2024: Filed a Manifestation and Motion relative to the December 12, 2024 hearing in view of the information relayed by the PAO counsel that defendant has no witness to present on said hearing date.'),
  (28, 'Awaiting a copy of the Court''s Order.'),
  (29, 'Note: May we request the RPMO to check with the court staff the available hearing dates for next year for the purpose of scheduling the hearing dates for DOST-RO2''s rebuttal witnesses. The OSG will provide two dates when it files a Comment on defendant''s FOE.'),
  (30, 'JANUARY 2025 – MARCH 2025: Received defendant''s Formal Offer of Evidence (FOE) on January 6, 2025 and thereafter filed on January 14, 2025 a Comment thereon.'),
  (31, 'Discussed with RPMO the possible rebuttal witness/es to be presented and the timeline of the taking of Judicial Affidavit (JA) until submission to the trial court.'),
  (32, 'Received on February 11, 2025 an Order resolving defendant''s formal offer of evidence and setting the presentation of rebuttal evidence on March 3 and 27, 2025. Under said Order, defendant''s Exhibits "1", "4" to "7", "10", "13" and "15" were admitted in evidence, while Exhibits "2", "3" (Certification of Lucio Calimag), "8", "11" and "14" were not admitted.'),
  (33, 'Attended virtual meetings with Clarenet Balderas in preparation for the taking of her JA.'),
  (34, 'Took the JA of Clarenet Balderas through videoconference and thereafter electronically filed the same before the Court under Submission dated February 25, 2025.'),
  (35, 'Conducted briefing with Clarenet Balderas on March 2, 2025 and presented her as a witness during the March 3, 2025 hearing.'),
  (36, 'Took the JA of Mary Ann Carpiso through videoconference and thereafter electronically filed the same before the Court under Submission dated March 19, 2025.'),
  (37, 'Conducted briefing with Mary Ann Carpiso and presented her as a witness during the March 27, 2025 hearing.'),
  (38, 'Electronically filed a Formal Offer of Rebuttal Evidence on March 31, 2025.'),
  (39, 'APRIL 2025 – MAY 2025: Electronically filed a Memorandum on May 21, 2025.'),
  (40, 'Under Order dated May 28, 2025, the case is now submitted for resolution.'),
  (41, 'JUNE 2025 – DECEMBER 2025: Filed a Notice of Appeal on December 5, 2025.')
) AS v(sort_order, body)
WHERE c.code = 'c-usigan-001';

