-- PHASE 3: INSERT verbatim Status/Remarks
INSERT INTO public.case_status_updates (case_id, sort_order, body)
SELECT c.id, v.sort_order, v.body
FROM public.cases c
CROSS JOIN (VALUES
  (1, 'JANUARY 2023 – JUNE 2023: Complaint with Judicial Affidavits already filed with the court.'),
  (2, 'JANUARY 2024 – AUGUST 2024: Pending verification as to whether defendant filed an Answer. OSG received on July 11, 2024 an Order dated June 28, 2024, dismissing the case without prejudice on the ground of plaintiff''s failure to prosecute.'),
  (3, 'Prepared an Omnibus Motion dated July 17, 2024, praying that the Court declare defendant in default and thereafter render judgment granting to plaintiff the relief prayed for in its Complaint.'),
  (4, 'Under letter dated July 17, 2024, the DOST-RO2 requested to personally serve and file said Omnibus Motion on or before July 26, 2024. Considering that the request cannot be accomplished before the due date, the OSG served and filed on July 26, 2024 the Omnibus Motion via registered mail.'),
  (5, 'SEPTEMBER 2024 – OCTOBER 2024: Filed a Manifestation and Motion dated September 18, 2024 on September 19, 2024.'),
  (6, 'Sent an email outlining the instructions for the September 20, 2024 Hearing.'),
  (7, 'Attended the October 17, 2024 Hearing.'),
  (8, 'Next scheduled hearing (ex parte presentation of evidence/witnesses before the Branch Clerk of Court) is on December 5, 2024 at 1:00 P.M.'),
  (9, 'NOVEMBER 2024 – DECEMBER 2024: Attended the ex parte hearing on December 5, 2024 in the afternoon, presented two DOST-RO2 witnesses (Daisy Simon and Nancy C. Guimmayen) and formally offered plaintiff''s evidence.'),
  (10, 'Awaiting a copy of the Court''s Order but the case is deemed submitted for resolution.'),
  (11, 'JANUARY 2025 – MARCH 2025: Received on January 7, 2025 an Order admitting plaintiffs'' Exhibits "A" to "W" and thereafter submitting the case for resolution.'),
  (12, 'APRIL 2025 – MAY 2025: Received through email on May 13, 2025 the favorable Judgment in the case.'),
  (13, 'Transmitted a copy thereof, both electronic and physical, to RPMO and RD on May 20 and 21, 2025, respectively.'),
  (14, 'JUNE 2025 – DECEMBER 2025: Transmitted a copy of the Judgment dated March 31, 2025, both electronic and physical, to RPMO and RD on May 20 and 21, 2025, respectively.'),
  (15, 'NOTE: Similar with the cases against Fe Corazon Chavez-Tiongson and Edwin Carabbacan, there is a need for RPMO to check the court record regarding defendant''s receipt of the Judgment or determine whether any motion for reconsideration or notice of appeal was filed by defendant. If defendant has received said Judgment and did not file a motion/notice of appeal, DOST-RO2 should secure a Certificate of Finality and forward it to the OSG for the filing of a Motion for Issuance of Writ of Execution.')
) AS v(sort_order, body)
WHERE c.code = 'c-magana-001';

